package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.widget.TextView;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import java.io.File;import java.util.concurrent.*;import org.junit.Test;import static org.junit.Assert.*;
/** Native inert configuration and private persistence; fake scheduling and movement availability only. */
public final class PowerNapFlowTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final UiDevice d=UiDevice.getInstance(i);PowerNapFixture f;
 interface Check{boolean ready()throws Exception;}void await(String action,Check check)throws Exception{long end=SystemClock.elapsedRealtime()+12000;while(!check.ready()){if(SystemClock.elapsedRealtime()>end)throw new AssertionError(action);Thread.sleep(25);}}
 View find(View v,String label,boolean description){if(v==null)return null;if(description?label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()):v instanceof TextView&&label.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++){View child=find(g.getChildAt(n),label,description);if(child!=null)return child;}}return null;}
 Rect target(String label,boolean click){Rect[] result={null};i.runOnMainSync(()->{if(f.current==null||!f.current.hasWindowFocus())return;View root=f.current.getWindow().getDecorView();View v=find(root,label,true);if(v==null)v=find(root,label,false);if(click)while(v!=null&&!v.isClickable())v=v.getParent() instanceof View?(View)v.getParent():null;if(v==null||click&&!v.isEnabled())return;Rect visible=new Rect();if(!v.getGlobalVisibleRect(visible)||visible.width()!=v.getWidth()||visible.height()!=v.getHeight()){v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),true);return;}if(click&&(visible.width()<Design.dp(f.c,48)||visible.height()<Design.dp(f.c,48)))return;int[] xy=new int[2];v.getLocationOnScreen(xy);result[0]=new Rect(xy[0],xy[1],xy[0]+v.getWidth(),xy[1]+v.getHeight());});return result[0];}
 void frame()throws Exception{CountDownLatch committed=new CountDownLatch(1);i.runOnMainSync(()->{View v=f.current.getWindow().getDecorView();assertTrue(f.current.hasWindowFocus());v.getViewTreeObserver().registerFrameCommitCallback(committed::countDown);v.invalidate();});assertTrue(committed.await(5,TimeUnit.SECONDS));}
 void shown(String text)throws Exception{await("Visible "+text,()->target(text,false)!=null);frame();assertTrue(text,d.wait(Until.hasObject(By.text(text)),5000));}
 void configured()throws Exception{await("Power nap settings control",()->target("Minimum-rest mode",false)!=null);frame();assertTrue(d.wait(Until.hasObject(By.desc("Minimum-rest mode")),5000));}
 void click(String label)throws Exception{await("Clickable "+label,()->target(label,true)!=null);frame();Rect hit=target(label,true);assertNotNull(label,hit);assertTrue(d.click(hit.centerX(),hit.centerY()));}
 void launch(int id)throws Exception{NapActivity a=(NapActivity)i.startActivitySync(new Intent(f.c,NapActivity.class).putExtra("id",id).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));await("Focused nap",()->f.current==a&&a.hasWindowFocus());shown("Nap");}
 void recreate(String label)throws Exception{NapActivity old=f.current;Instrumentation.ActivityMonitor monitor=i.addMonitor(NapActivity.class.getName(),null,false);try{i.runOnMainSync(old::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}await("Recreated nap",()->f.current!=old&&f.current.hasWindowFocus());shown(label);}
 void capture(String suffix)throws Exception{frame();File folder=new File(f.c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(d.takeScreenshot(new File(folder,"power-nap-"+suffix+".png")));}
 @Test public void explicitIntervalsCancelDraftRecreateStartReopenAndCancelPersistWithoutOutputs()throws Exception{try(PowerNapFixture fixture=new PowerNapFixture()){f=fixture;try{f.delayWave=true;launch(0);await("Requested real waveform",()->f.waveRequested.getCount()==0);click("Configure power nap");configured();click("Back");shown("Nap");View[] configure={null};i.runOnMainSync(()->configure[0]=find(f.current.getWindow().getDecorView(),"Configure power nap",true));assertNotNull(configure[0]);f.waveRelease.countDown();await("Applied delayed actual waveform",()->{boolean[] ready={false};i.runOnMainSync(()->{View host=f.current.getWindow().getDecorView().findViewWithTag("nap-waveform");ready[0]=host instanceof android.widget.FrameLayout&&((android.widget.FrameLayout)host).getChildCount()==1;});return ready[0];});i.runOnMainSync(()->{assertSame("Waveform arrival must preserve the real action owner",configure[0],find(f.current.getWindow().getDecorView(),"Configure power nap",true));assertTrue(configure[0].isAttachedToWindow());});assertNull(f.saved());assertEquals(0,f.schedules);click("Configure power nap");configured();click("Minimum-rest mode");shown("Earliest wake after 20 min · latest after 35 min");click("Minimum rest 30 minutes");click("Later wake interval 60 minutes");shown("Earliest wake after 30 min · latest after 90 min");shown("Movement tracking is unavailable. The latest timer still works; no tracking starts here.");capture("settings");recreate("Power nap");shown("Earliest wake after 30 min · latest after 90 min");capture("recreated");click("Use nap interval");shown("Minimum rest");click("Smart wake-up");shown("Start phone movement tracking first, or keep Smart wake-up off.");assertNull(f.saved());f.motion=true;click("Smart wake-up");shown("Movement available · never before minimum rest");click("Start nap");await("Saved interval",()->f.saved()!=null&&f.saved().enabled&&f.saved().nap.phase==NapPlan.Phase.PENDING);Alarm saved=f.saved();assertEquals(30,saved.nap.minimumRestMinutes);assertEquals(90,saved.nap.minutes);assertEquals(60,saved.smartWindow);assertEquals(5400000,f.delay);assertEquals(1,f.schedules);assertEquals(0,f.fires);capture("pending");NapActivity previous=f.current;i.runOnMainSync(previous::finish);await("Finished initial nap",previous::isDestroyed);launch(saved.id);shown("30 min rest · 60 min wake interval");assertEquals(saved.nap.nonce,f.saved().nap.nonce);capture("reopened");click("Cancel nap");await("Durable cancel",()->!f.saved().enabled&&f.saved().nap.phase==NapPlan.Phase.CANCELLED);assertEquals(30,f.saved().nap.minimumRestMinutes);assertEquals(0,f.fires);assertTrue(f.cancels>0);}catch(Exception|AssertionError failure){try{File folder=new File(f.c.getExternalFilesDir(null),"verification");folder.mkdirs();d.takeScreenshot(new File(folder,"power-nap-failure.png"));d.dumpWindowHierarchy(new File(folder,"power-nap-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}}}
}
